import { type LucideIcon } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { useCountUp } from "@/hooks/use-count-up";
import { cn } from "@/lib/utils";
import { TrendingUp, TrendingDown } from "lucide-react";

interface KpiCardProps {
  title: string;
  value: number;
  prefix?: string;
  suffix?: string;
  trend?: number; // percentage change, positive = good
  trendLabel?: string;
  icon: LucideIcon;
  iconColor?: string;
  iconBg?: string;
  valueColor?: string;
}

export function KpiCard({
  title,
  value,
  prefix = "",
  suffix = "",
  trend,
  trendLabel = "vs last month",
  icon: Icon,
  iconColor = "text-primary",
  iconBg = "bg-primary/10",
  valueColor = "text-foreground",
}: KpiCardProps) {
  const animatedValue = useCountUp(value);
  const isPositiveTrend = trend !== undefined && trend > 0;

  return (
    <Card className="border-slate-200 shadow-none hover:shadow-sm transition-shadow duration-200">
      <CardContent className="p-6">
        <div className="flex items-start justify-between">
          <div className="space-y-2">
            <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
              {title}
            </p>
            <p className={cn("text-[48px] font-bold leading-none tracking-tight", valueColor)}>
              {prefix}{animatedValue.toLocaleString()}{suffix}
            </p>
          </div>
          <div className={cn("flex h-10 w-10 items-center justify-center rounded-lg", iconBg)}>
            <Icon className={cn("h-5 w-5", iconColor)} />
          </div>
        </div>
        {trend !== undefined && (
          <div className="mt-3 flex items-center gap-1.5">
            {isPositiveTrend ? (
              <TrendingUp className="h-3.5 w-3.5 text-green-500" />
            ) : (
              <TrendingDown className="h-3.5 w-3.5 text-red-500" />
            )}
            <span
              className={cn(
                "text-xs font-medium",
                isPositiveTrend ? "text-green-600" : "text-red-600"
              )}
            >
              {isPositiveTrend ? "+" : ""}
              {trend}%
            </span>
            <span className="text-xs text-muted-foreground">{trendLabel}</span>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

