import type { CroPillar, PageType, Severity } from "./index";

// ── Agent Roles & Status ────────────────────────────────────

export type AgentRole =
  | "orchestrator"
  | "content_analyzer"
  | "ux_auditor"
  | "performance_analyst"
  | "trust_evaluator"
