import type { AgentStatus, AgentTask, AgentMessage, TaskStatus } from "@/types/agents";
import { MOCK_AGENTS, MOCK_AGENT_MESSAGES } from "./mock-agents";

// ── Agent Engine ────────────────────────────────────────────
// Simulates real-time agent collaboration with progressive message
// delivery, status changes, and progress updates.

type Listener = () => void;

interface EngineState {
  agentStatuses: Record<string, AgentStatus>;
  taskProgress: Record<string, number>;
  taskStatus: Record<string, TaskStatus>;
  visibleMessages: Record<string, AgentMessage[]>;
  activeTaskId: string | null;
}

class AgentEngine {
  private state: EngineState;
  private listeners: Set<Listener> = new Set();
  private timers: ReturnType<typeof setTimeout>[] = [];
  private messageQueue: Map<string, AgentMessage[]> = new Map();

  constructor() {
    // Initialize agent statuses
    const agentStatuses: Record<string, AgentStatus> = {};
    MOCK_AGENTS.forEach((a) => {
      agentStatuses[a.id] = a.status;
    });

    this.state = {
      agentStatuses,
      taskProgress: {},
      taskStatus: {},
      visibleMessages: {},
      activeTaskId: null,
    };
  }

  // ── Subscription ────────────────────────────────────

  subscribe(listener: Listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private notify() {
    this.listeners.forEach((fn) => fn());
  }

  getState() {
    return this.state;
  }

  // ── Start watching a task (progressive message delivery) ──

  watchTask(taskId: string) {
    if (this.state.activeTaskId === taskId) return;

    this.cleanup();
    this.state.activeTaskId = taskId;

    // Get all messages for this task
    const taskMessages = MOCK_AGENT_MESSAGES.filter(
      (m) => m.task_id === taskId
    );

    if (!taskMessages.length) {
      this.state.visibleMessages[taskId] = [];
      this.notify();
      return;
    }

    // Queue messages for progressive delivery
    this.messageQueue.set(taskId, [...taskMessages]);
    this.state.visibleMessages[taskId] = [];

    // Set agents to working
    const agentIds = new Set(taskMessages.map((m) => m.agent_id));
    agentIds.forEach((id) => {
      this.state.agentStatuses[id] = "working";
    });

    this.notify();

    // Deliver messages one by one with realistic delays
    this.deliverNextMessage(taskId);
  }

  private deliverNextMessage(taskId: string) {
    const queue = this.messageQueue.get(taskId);
    if (!queue || queue.length === 0) return;

    const message = queue.shift()!;

    // Determine delay based on message type
    let delay = 800;
    if (message.type === "thinking") delay = 600;
    if (message.type === "finding") delay = 1400;
    if (message.type === "suggestion") delay = 1800;
    if (message.type === "handoff") delay = 1000;
    if (message.type === "milestone") delay = 1200;
    if (message.type === "action") delay = 700;

    const timer = setTimeout(() => {
      // Update agent status based on message type
      if (message.type === "thinking") {
        this.state.agentStatuses[message.agent_id] = "thinking";
      } else if (message.type === "finding" || message.type === "suggestion") {
        this.state.agentStatuses[message.agent_id] = "working";
      } else if (message.type === "milestone") {
        this.state.agentStatuses[message.agent_id] = "reviewing";
      }

      // Add message to visible messages
      if (!this.state.visibleMessages[taskId]) {
        this.state.visibleMessages[taskId] = [];
      }
      this.state.visibleMessages[taskId] = [
        ...this.state.visibleMessages[taskId],
        message,
      ];

      // Update progress
      const total = MOCK_AGENT_MESSAGES.filter(
        (m) => m.task_id === taskId
      ).length;
      const delivered = this.state.visibleMessages[taskId].length;
      this.state.taskProgress[taskId] = Math.round(
        (delivered / total) * 100
      );

      this.notify();

      // Continue delivering
      if (queue.length > 0) {
        this.deliverNextMessage(taskId);
      } else {
        // All messages delivered — set agents to completed
        const agentIds = new Set(
          MOCK_AGENT_MESSAGES.filter((m) => m.task_id === taskId).map(
            (m) => m.agent_id
          )
        );
        agentIds.forEach((id) => {
          this.state.agentStatuses[id] = "completed";
        });
        this.state.taskStatus[taskId] = "completed";
        this.notify();
      }
    }, delay);

    this.timers.push(timer);
  }

  // ── Load all messages instantly (for completed tasks) ─────

  loadCompletedTask(taskId: string) {
    const taskMessages = MOCK_AGENT_MESSAGES.filter(
      (m) => m.task_id === taskId
    );
    this.state.visibleMessages[taskId] = taskMessages;
    this.state.taskProgress[taskId] = 100;
    this.state.taskStatus[taskId] = "completed";
    this.state.activeTaskId = taskId;

    const agentIds = new Set(taskMessages.map((m) => m.agent_id));
    agentIds.forEach((id) => {
      this.state.agentStatuses[id] = "completed";
    });

    this.notify();
  }

  // ── Cleanup timers ────────────────────────────────────

  cleanup() {
    this.timers.forEach(clearTimeout);
    this.timers = [];
    this.messageQueue.clear();

    // Reset agents to idle
    MOCK_AGENTS.forEach((a) => {
      this.state.agentStatuses[a.id] = "idle";
    });
  }

  // ── Get visible messages for a task ───────────────────

  getMessages(taskId: string): AgentMessage[] {
    return this.state.visibleMessages[taskId] ?? [];
  }

  // ── Get agent status ──────────────────────────────────

  getAgentStatus(agentId: string): AgentStatus {
    return this.state.agentStatuses[agentId] ?? "idle";
  }

  // ── Get task progress (0-100) ─────────────────────────

  getTaskProgress(taskId: string): number {
    return this.state.taskProgress[taskId] ?? 0;
  }
}

// Singleton engine instance
export const agentEngine = new AgentEngine();

