import { Card, CardContent } from "@/components/ui/card";
import { AgentAvatar } from "./AgentAvatar";
import { AgentStatusBadge } from "./AgentStatusBadge";
import { cn } from "@/lib/utils";
import type { CroAgent } from "@/types/agents";

interface AgentCardProps {
  agent: CroAgent;
  compact?: boolean;
  onClick?: () => void;
  className?: string;
}

export function AgentCard({ agent, compact = false, onClick, className }: AgentCardProps) {
  if (compact) {
    return (
      <div
        className={cn(
          "flex items-center gap-3 rounded-xl border border-slate-200 bg-white p-3 transition-all hover:border-slate-300 hover:shadow-sm",
          onClick && "cursor-pointer",
          className
        )}
        onClick={onClick}
      >
        <AgentAvatar
          emoji={agent.emoji}
          gradient={agent.gradient}
          status={agent.status}
          size="sm"
        />
        <div className="min-w-0 flex-1">
          <p className="text-sm font-medium text-foreground truncate">
            {agent.name}
          </p>
          <p className="text-xs text-muted-foreground truncate">
            {agent.description}
          </p>
        </div>
        <AgentStatusBadge status={agent.status} />
      </div>
    );
  }

  return (
    <Card
      className={cn(
        "border-slate-200 shadow-none hover:shadow-md transition-all duration-200 overflow-hidden group",
        onClick && "cursor-pointer",
        className
      )}
      onClick={onClick}
    >
      {/* Gradient top bar */}
      <div className={cn("h-1 bg-gradient-to-r", agent.gradient)} />
      <CardContent className="p-5">
        <div className="flex items-start justify-between mb-4">
          <AgentAvatar
            emoji={agent.emoji}
            gradient={agent.gradient}
            status={agent.status}
            size="lg"
          />
          <AgentStatusBadge status={agent.status} />
        </div>

        <h3 className="text-base font-semibold text-foreground mb-1">
          {agent.name}
        </h3>
        <p className="text-xs text-muted-foreground leading-relaxed mb-4 line-clamp-2">
          {agent.description}
        </p>

        {/* Stats */}
        <div className="grid grid-cols-3 gap-3 pt-3 border-t border-slate-100">
          <div>
            <p className="text-xs text-muted-foreground">Tasks</p>
            <p className="text-sm font-semibold text-foreground tabular-nums">
              {agent.stats.tasks_completed}
            </p>
          </div>
          <div>
            <p className="text-xs text-muted-foreground">Avg Finds</p>
            <p className="text-sm font-semibold text-foreground tabular-nums">
              {agent.stats.avg_findings}
            </p>
          </div>
          <div>
            <p className="text-xs text-muted-foreground">Accuracy</p>
            <p className="text-sm font-semibold text-foreground tabular-nums">
              {agent.stats.accuracy}%
            </p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

