import { Link } from "react-router-dom";
import { ArrowUpRight, Clock, AlertTriangle, Globe } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Button } from "@/components/ui/button";
import { AgentAvatar } from "./AgentAvatar";
import { cn } from "@/lib/utils";
import { formatRelativeDate } from "@/lib/score-utils";
import { MOCK_AGENTS } from "@/lib/mock-agents";
import type { AgentTask } from "@/types/agents";

interface TaskCardProps {
  task: AgentTask;
  className?: string;
}

const priorityConfig: Record<
  string,
  { label: string; bg: string; text: string; border: string }
> = {
  critical: {
    label: "Critical",
    bg: "bg-red-50",
    text: "text-red-700",
    border: "border-red-200",
  },
  high: {
    label: "High",
    bg: "bg-orange-50",
    text: "text-orange-700",
    border: "border-orange-200",
  },
  medium: {
    label: "Medium",
    bg: "bg-blue-50",
    text: "text-blue-700",
    border: "border-blue-200",
  },
  low: {
    label: "Low",
    bg: "bg-slate-50",
    text: "text-slate-600",
    border: "border-slate-200",
  },
};

const statusConfig: Record<
  string,
  { label: string; bg: string; text: string; border: string }
> = {
  queued: {
    label: "Queued",
    bg: "bg-slate-50",
    text: "text-slate-600",
    border: "border-slate-200",
  },
  in_progress: {
    label: "In Progress",
    bg: "bg-blue-50",
    text: "text-blue-700",
    border: "border-blue-200",
  },
  reviewing: {
    label: "Reviewing",
    bg: "bg-violet-50",
    text: "text-violet-700",
    border: "border-violet-200",
  },
  completed: {
    label: "Completed",
    bg: "bg-emerald-50",
    text: "text-emerald-700",
    border: "border-emerald-200",
  },
  failed: {
    label: "Failed",
    bg: "bg-red-50",
    text: "text-red-700",
    border: "border-red-200",
  },
};

export function TaskCard({ task, className }: TaskCardProps) {
  const priority = priorityConfig[task.priority];
  const status = statusConfig[task.status];
  const isActive = task.status === "in_progress" || task.status === "reviewing";
  const assignedAgents = MOCK_AGENTS.filter((a) =>
    task.assigned_agents.includes(a.id)
  );

  let hostname = "";
  try {
    hostname = new URL(task.url).hostname.replace("www.", "");
  } catch {
    hostname = task.url;
  }

  return (
    <Card
      className={cn(
        "border-slate-200 shadow-none hover:shadow-md transition-all duration-200 overflow-hidden group",
        isActive && "border-blue-200 shadow-sm",
        className
      )}
    >
      {isActive && (
        <div className="h-0.5 bg-gradient-to-r from-blue-500 via-violet-500 to-purple-500 animate-pulse" />
      )}
      <CardContent className="p-5">
        {/* Header: Status + Priority */}
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <Badge
              variant="outline"
              className={cn(
                "text-[10px]",
                status.bg,
                status.text,
                status.border
              )}
            >
              {status.label}
            </Badge>
            <Badge
              variant="outline"
              className={cn(
                "text-[10px]",
                priority.bg,
                priority.text,
                priority.border
              )}
            >
              {priority.label}
            </Badge>
          </div>
          <span className="text-xs text-muted-foreground">
            {formatRelativeDate(task.created_at)}
          </span>
        </div>

        {/* Title */}
        <h3 className="text-sm font-semibold text-foreground mb-1 leading-snug">
          {task.title}
        </h3>

        {/* URL */}
        <div className="flex items-center gap-1.5 mb-3">
          <Globe className="h-3 w-3 text-muted-foreground" />
          <span className="text-xs text-muted-foreground truncate">
            {hostname}
          </span>
        </div>

        {/* Progress bar (only for active tasks) */}
        {isActive && (
          <div className="mb-3">
            <div className="flex items-center justify-between mb-1">
              <span className="text-xs text-muted-foreground">Progress</span>
              <span className="text-xs font-medium text-foreground tabular-nums">
                {task.progress}%
              </span>
            </div>
            <Progress value={task.progress} className="h-1.5" />
          </div>
        )}

        {/* Stats row */}
        <div className="flex items-center gap-4 mb-4 text-xs text-muted-foreground">
          {task.findings_count > 0 && (
            <div className="flex items-center gap-1">
              <AlertTriangle className="h-3 w-3" />
              <span>
                {task.findings_count} findings
                {task.critical_findings > 0 && (
                  <span className="text-red-500 font-medium ml-1">
                    ({task.critical_findings} critical)
                  </span>
                )}
              </span>
            </div>
          )}
          <div className="flex items-center gap-1">
            <Clock className="h-3 w-3" />
            <span>{task.estimated_duration}</span>
          </div>
        </div>

        {/* Assigned agents + View button */}
        <div className="flex items-center justify-between pt-3 border-t border-slate-100">
          <div className="flex items-center">
            <div className="flex -space-x-2">
              {assignedAgents.slice(0, 5).map((agent) => (
                <AgentAvatar
                  key={agent.id}
                  emoji={agent.emoji}
                  gradient={agent.gradient}
                  status={agent.status}
                  size="sm"
                  showStatus={false}
                  className="ring-2 ring-white"
                />
              ))}
            </div>
            {assignedAgents.length > 5 && (
              <span className="ml-2 text-xs text-muted-foreground">
                +{assignedAgents.length - 5}
              </span>
            )}
          </div>

          <Button
            variant="ghost"
            size="sm"
            asChild
            className="text-primary hover:text-primary opacity-0 group-hover:opacity-100 transition-opacity"
          >
            <Link to={`/agents/${task.id}`}>
              {isActive ? "Watch Live" : "View Details"}
              <ArrowUpRight className="ml-1 h-3 w-3" />
            </Link>
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

