            <Clock className="h-3 w-3" />
            <span>{task.estimated_duration}</span>
          </div>
        </div>

        {/* Assigned agents + View button */}
        <div className="flex items-center justify-between pt-3 border-t border-slate-100">
          <div className="flex items-center">
            <div className="flex -space-x-2">
              {assignedAgents.slice(0, 5).map((agent) => (
                <AgentAvatar
                  key={agent.id}
                  emoji={agent.emoji}
                  gradient={agent.gradient}
                  status={agent.status}
                  size="sm"
                  showStatus={false}
                  className="ring-2 ring-white"
                />
              ))}
            </div>
            {assignedAgents.length > 5 && (
              <span className="ml-2 text-xs text-muted-foreground">
                +{assignedAgents.length - 5}
              </span>
            )}
          </div>

          <Button
            variant="ghost"
            size="sm"
            asChild
            className="text-primary hover:text-primary opacity-0 group-hover:opacity-100 transition-opacity"
          >
            <Link to={`/agents/${task.id}`}>
              {isActive ? "Watch Live" : "View Details"}
              <ArrowUpRight className="ml-1 h-3 w-3" />
            </Link>
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

