import {
  Lightbulb,
  AlertTriangle,
  ArrowRightLeft,
  MessageCircle,
  Sparkles,
  Flag,
  Cog,
  Brain,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { AgentAvatar } from "./AgentAvatar";
import { cn } from "@/lib/utils";
import { MOCK_AGENTS } from "@/lib/mock-agents";
import type { AgentMessage as AgentMessageType, MessageType } from "@/types/agents";

interface AgentMessageProps {
  message: AgentMessageType;
  isLatest?: boolean;
}

const typeConfig: Record<
  MessageType,
  {
    icon: typeof Lightbulb;
    iconColor: string;
    bgColor: string;
    borderColor: string;
    label: string;
  }
> = {
  thinking: {
    icon: Brain,
    iconColor: "text-amber-500",
    bgColor: "bg-amber-50/50",
    borderColor: "border-amber-100",
    label: "Thinking",
  },
  finding: {
    icon: AlertTriangle,
    iconColor: "text-red-500",
    bgColor: "bg-red-50/30",
    borderColor: "border-red-100",
    label: "Finding",
  },
  suggestion: {
    icon: Sparkles,
    iconColor: "text-violet-500",
    bgColor: "bg-violet-50/30",
    borderColor: "border-violet-100",
    label: "Suggestion",
  },
  handoff: {
    icon: ArrowRightLeft,
    iconColor: "text-blue-500",
    bgColor: "bg-blue-50/30",
    borderColor: "border-blue-100",
    label: "Handoff",
  },
  question: {
    icon: MessageCircle,
    iconColor: "text-cyan-500",
    bgColor: "bg-cyan-50/30",
    borderColor: "border-cyan-100",
    label: "Question",
  },
  summary: {
    icon: Lightbulb,
    iconColor: "text-emerald-500",
    bgColor: "bg-emerald-50/30",
    borderColor: "border-emerald-100",
    label: "Summary",
  },
  action: {
    icon: Cog,
    iconColor: "text-slate-500",
    bgColor: "bg-slate-50/50",
    borderColor: "border-slate-100",
    label: "Action",
  },
  milestone: {
    icon: Flag,
    iconColor: "text-green-500",
    bgColor: "bg-green-50/30",
    borderColor: "border-green-100",
    label: "Milestone",
  },
};

const severityColors: Record<string, string> = {
  critical: "bg-red-50 text-red-700 border-red-200",
  warning: "bg-amber-50 text-amber-700 border-amber-200",
  info: "bg-blue-50 text-blue-700 border-blue-200",
  passed: "bg-emerald-50 text-emerald-700 border-emerald-200",
};

export function AgentMessageBubble({ message, isLatest = false }: AgentMessageProps) {
  const agent = MOCK_AGENTS.find((a) => a.id === message.agent_id);
  const config = typeConfig[message.type];
  const Icon = config.icon;

  if (!agent) return null;

  const time = new Date(message.timestamp).toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
  });

  // Find target agent for handoffs
  const targetAgent = message.metadata?.target_agent
    ? MOCK_AGENTS.find((a) => a.id === message.metadata?.target_agent)
    : null;

  return (
    <div
      className={cn(
        "group relative flex gap-3 rounded-xl border p-4 transition-all duration-300",
        config.bgColor,
        config.borderColor,
        isLatest && "animate-fade-in ring-1 ring-primary/10 shadow-sm"
      )}
    >
      {/* Agent Avatar */}
      <AgentAvatar
        emoji={agent.emoji}
        gradient={agent.gradient}
        size="sm"
        showStatus={false}
        className="shrink-0 mt-0.5"
      />

      {/* Content */}
      <div className="flex-1 min-w-0">
        {/* Header */}
        <div className="flex items-center gap-2 mb-1.5 flex-wrap">
          <span className="text-sm font-semibold text-foreground">
            {agent.name}
          </span>
          <span
            className={cn(
              "inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-medium",
              config.bgColor,
              config.iconColor
            )}
          >
            <Icon className="h-2.5 w-2.5" />
            {config.label}
          </span>
          {message.metadata?.severity && (
            <Badge
              variant="outline"
              className={cn(
                "text-[10px] uppercase",
                severityColors[message.metadata.severity]
              )}
            >
              {message.metadata.severity}
            </Badge>
          )}
          <span className="text-[10px] text-muted-foreground ml-auto">
            {time}
          </span>
        </div>

        {/* Message body */}
        <div className="text-sm text-foreground/90 leading-relaxed whitespace-pre-line">
          {message.content}
        </div>

        {/* Metadata */}
        {(message.metadata?.confidence || message.metadata?.impact || targetAgent) && (
          <div className="flex items-center gap-3 mt-2 pt-2 border-t border-slate-100 flex-wrap">
            {message.metadata?.confidence && (
              <span className="text-[10px] text-muted-foreground">
                Confidence:{" "}
                <span className="font-medium text-foreground">
                  {message.metadata.confidence}%
                </span>
              </span>
            )}
            {message.metadata?.impact && (
              <span className="text-[10px] text-muted-foreground">
                Impact:{" "}
                <span className="font-medium text-green-600">
                  {message.metadata.impact}
                </span>
              </span>
            )}
            {targetAgent && (
              <span className="text-[10px] text-muted-foreground flex items-center gap-1">
                Handed off to{" "}
                <span className="font-medium text-foreground">
                  {targetAgent.emoji} {targetAgent.name}
                </span>
              </span>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

