import { AgentAvatar } from "./AgentAvatar";
import { cn } from "@/lib/utils";
import { formatRelativeDate } from "@/lib/score-utils";
import { MOCK_AGENTS } from "@/lib/mock-agents";
import type { AgentActivity } from "@/types/agents";

interface AgentActivityFeedProps {
  activities: AgentActivity[];
  maxItems?: number;
  className?: string;
}

const actionColors: Record<string, string> = {
  "Task initiated": "text-violet-600",
  "Started analysis": "text-blue-600",
  "Critical finding": "text-red-600",
  "Copy generation": "text-indigo-600",
  "Task completed": "text-emerald-600",
};

export function AgentActivityFeed({
  activities,
  maxItems = 10,
  className,
}: AgentActivityFeedProps) {
  const items = activities.slice(0, maxItems);

  return (
    <div className={cn("space-y-0", className)}>
      {items.map((activity, idx) => {
        const agent = MOCK_AGENTS.find((a) => a.id === activity.agent_id);
        if (!agent) return null;

        const isLast = idx === items.length - 1;
        const actionColor = actionColors[activity.action] ?? "text-foreground";

        return (
          <div key={activity.id} className="relative flex gap-3 pb-4">
            {/* Timeline connector */}
            {!isLast && (
              <div className="absolute left-[15px] top-9 bottom-0 w-px bg-slate-200" />
            )}

            <AgentAvatar
              emoji={agent.emoji}
              gradient={agent.gradient}
              size="sm"
              showStatus={false}
              className="shrink-0 z-10"
            />

            <div className="flex-1 min-w-0 pt-0.5">
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <span className="text-sm font-medium text-foreground">
                    {agent.name}
                  </span>
                  <span className={cn("text-sm ml-1.5", actionColor)}>
                    {activity.action.toLowerCase()}
                  </span>
                </div>
                <span className="text-[10px] text-muted-foreground whitespace-nowrap shrink-0">
                  {formatRelativeDate(activity.timestamp)}
                </span>
              </div>
              <p className="text-xs text-muted-foreground mt-0.5 truncate">
                {activity.detail}
              </p>
            </div>
          </div>
        );
      })}
    </div>
  );
}

