input.content:
import { useState } from "react";
import { Sparkles, Globe, ChevronDown } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { AgentAvatar } from "./AgentAvatar";
import { cn } from "@/lib/utils";
import { MOCK_AGENTS } from "@/lib/mock-agents";
import { PAGE_TYPES } from "@/lib/constants";

interface NewTaskDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

type AuditType = "full" | "focused" | "rewrite";

const auditTypes: { value: AuditType; label: string; description: string; agents: string[] }[] = [
  {
    value: "full",
    label: "Full CRO Audit",
    description: "All 7 pillars analyzed by the complete agent team",
    agents: ["agent_prime", "agent_clarity", "agent_converge", "agent_shield", "agent_prism", "agent_pocket", "agent_blitz", "agent_quill"],
  },
  {
    value: "focused",
    label: "Focused Deep Dive",
    description: "Target specific pillars for deeper analysis",
    agents: ["agent_prime"],
  },
  {
    value: "rewrite",
    label: "AI Copy Rewrite",
    description: "Generate conversion-optimized copy alternatives",
    agents: ["agent_prime", "agent_clarity", "agent_quill"],
  },
];

export function NewTaskDialog({ open, onOpenChange }: NewTaskDialogProps) {
  const [url, setUrl] = useState("");
  const [auditType, setAuditType] = useState<AuditType>("full");
  const [pageType, setPageType] = useState("");
  const [notes, setNotes] = useState("");

  const selectedAudit = auditTypes.find((a) => a.value === auditType)!;
  const selectedAgents = MOCK_AGENTS.filter((a) =>
    selectedAudit.agents.includes(a.id)
  );

  const handleSubmit = () => {
    // In production: this would dispatch to the agent engine
    onOpenChange(false);
    setUrl("");
    setNotes("");
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[560px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-lg">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-violet-500 to-purple-600">
              <Sparkles className="h-4 w-4 text-white" />
            </div>
            New Agent Task
          </DialogTitle>
          <DialogDescription>
            Deploy AI agents to autonomously analyze and optimize any page.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5 pt-2">
          {/* URL Input */}
          <div className="space-y-2">
            <Label htmlFor="task-url">Page URL</Label>
            <div className="relative">
              <Globe className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                id="task-url"
                placeholder="https://example.com/landing-page"
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                className="pl-10"
              />
            </div>
          </div>

          {/* Audit Type Selection */}
          <div className="space-y-2">
            <Label>Audit Type</Label>
            <div className="grid grid-cols-3 gap-2">
              {auditTypes.map((type) => (
                <button
                  key={type.value}
                  onClick={() => setAuditType(type.value)}
                  className={cn(
                    "rounded-xl border p-3 text-left transition-all hover:border-primary/50",
                    auditType === type.value
                      ? "border-primary bg-primary/5 ring-1 ring-primary/20"
                      : "border-slate-200"
                  )}
                >
                  <p className="text-xs font-semibold text-foreground">
                    {type.label}
                  </p>
                  <p className="text-[10px] text-muted-foreground mt-0.5 leading-relaxed">
                    {type.description}
                  </p>
                </button>
              ))}
            </div>
          </div>

          {/* Page Type */}
          <div className="space-y-2">
            <Label>Page Type</Label>
            <Select value={pageType} onValueChange={setPageType}>
              <SelectTrigger>
                <SelectValue placeholder="Auto-detect (recommended)" />
              </SelectTrigger>
              <SelectContent>
                {PAGE_TYPES.map((pt) => (
                  <SelectItem key={pt.value} value={pt.value}>
                    {pt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Notes */}
          <div className="space-y-2">
            <Label htmlFor="task-notes">
              Notes{" "}
              <span className="text-muted-foreground font-normal">
                (optional)
              </span>
            </Label>
            <Textarea
              id="task-notes"
              placeholder="Any specific areas to focus on, business context, or goals..."
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              rows={2}
            />
          </div>

          {/* Assigned Agents Preview */}
          <div className="rounded-xl border border-slate-200 bg-slate-50/50 p-3">
            <p className="text-xs font-medium text-muted-foreground mb-2">
              Agents assigned to this task
            </p>
            <div className="flex flex-wrap gap-2">
              {selectedAgents.map((agent) => (
                <div
                  key={agent.id}
                  className="flex items-center gap-1.5 rounded-full bg-white border border-slate-200 pl-1 pr-2.5 py-1"
                >
                  <AgentAvatar
                    emoji={agent.emoji}
                    gradient={agent.gradient}
                    size="sm"
                    showStatus={false}
                  />
                  <span className="text-xs font-medium text-foreground">
                    {agent.name}
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* Submit */}
          <Button
            onClick={handleSubmit}
            disabled={!url.trim()}
            className="w-full bg-gradient-to-r from-violet-600 to-purple-600 hover:from-violet-700 hover:to-purple-700 text-white shadow-lg shadow-violet-500/20"
            size="lg"
          >
            <Sparkles className="mr-2 h-4 w-4" />
            Deploy Agents
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

