import { useState } from "react";
import {
  Plus,
  Bot,
  Activity,
  Zap,
  ListChecks,
  ArrowRight,
  Filter,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { PageTransition } from "@/components/shared/PageTransition";
import { KpiCard } from "@/components/shared/KpiCard";
import { AgentCard } from "@/components/agents/AgentCard";
import { TaskCard } from "@/components/agents/TaskCard";
import { AgentActivityFeed } from "@/components/agents/AgentActivityFeed";
import { NewTaskDialog } from "@/components/agents/NewTaskDialog";
import { MOCK_AGENTS, MOCK_AGENT_TASKS, MOCK_AGENT_ACTIVITY } from "@/lib/mock-agents";
import type { TaskStatus } from "@/types/agents";

// ── Derived data ────────────────────────────────────────────

const activeTasks = MOCK_AGENT_TASKS.filter(
  (t) => t.status === "in_progress" || t.status === "reviewing"
);
const completedTasks = MOCK_AGENT_TASKS.filter(
  (t) => t.status === "completed"
);
const queuedTasks = MOCK_AGENT_TASKS.filter((t) => t.status === "queued");

const totalFindings = MOCK_AGENT_TASKS.reduce(
  (sum, t) => sum + t.findings_count,
  0
);
const criticalFindings = MOCK_AGENT_TASKS.reduce(
  (sum, t) => sum + t.critical_findings,
  0
);

const activeAgents = MOCK_AGENTS.filter(
  (a) => a.status !== "idle" && a.status !== "completed"
);

// ── Component ───────────────────────────────────────────────

const AgentHub = () => {
  const [showNewTask, setShowNewTask] = useState(false);
  const [taskFilter, setTaskFilter] = useState<"all" | TaskStatus>("all");

  const filteredTasks =
    taskFilter === "all"
      ? MOCK_AGENT_TASKS
      : MOCK_AGENT_TASKS.filter((t) => t.status === taskFilter);

  return (
    <PageTransition>
      <div className="space-y-8">
        {/* ── Header ───────────────────────────────────────── */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <div className="flex items-center gap-3 mb-1">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-violet-500 to-purple-600 shadow-lg shadow-violet-500/20">
                <Bot className="h-5 w-5 text-white" />
              </div>
              <h2 className="text-[28px] font-bold text-foreground">
                AI Agent Hub
              </h2>
            </div>
            <p className="text-sm text-muted-foreground">
              Deploy autonomous AI agents that collaboratively analyze and optimize any page for conversions.
            </p>
          </div>
          <Button
            onClick={() => setShowNewTask(true)}
            className="bg-gradient-to-r from-violet-600 to-purple-600 hover:from-violet-700 hover:to-purple-700 text-white shadow-lg shadow-violet-500/20"
            size="lg"
          >
            <Plus className="mr-2 h-4 w-4" />
            New Agent Task
          </Button>
        </div>

        {/* ── KPI Cards ────────────────────────────────────── */}
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
          <KpiCard
            title="Active Agents"
            value={activeAgents.length}
            suffix={` / ${MOCK_AGENTS.length}`}
            icon={Bot}
            iconBg="bg-violet-50"
            iconColor="text-violet-500"
          />
          <KpiCard
            title="Tasks In Progress"
            value={activeTasks.length}
            icon={Activity}
            iconBg="bg-blue-50"
            iconColor="text-blue-500"
          />
          <KpiCard
            title="Findings Generated"
            value={totalFindings}
            icon={Zap}
            iconBg="bg-amber-50"
            iconColor="text-amber-500"
          />
          <KpiCard
            title="Tasks Completed"
            value={completedTasks.length}
            icon={ListChecks}
            iconBg="bg-emerald-50"
            iconColor="text-emerald-500"
          />
        </div>

        {/* ── Main Content: Tasks + Sidebar ─────────────────── */}
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
          {/* Left: Task Board (2 cols) */}
          <div className="lg:col-span-2 space-y-6">
            {/* Active Tasks Section */}
            {activeTasks.length > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <div className="h-2 w-2 rounded-full bg-blue-500 animate-pulse" />
                  <h3 className="text-sm font-semibold text-foreground uppercase tracking-wider">
                    Live — Agents Working
                  </h3>
                  <Badge variant="outline" className="text-[10px] border-blue-200 bg-blue-50 text-blue-700">
                    {activeTasks.length} active
                  </Badge>
                </div>
                <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                  {activeTasks.map((task) => (
                    <TaskCard key={task.id} task={task} />
                  ))}
                </div>
              </div>
            )}

            {/* All Tasks */}
            <div>
              <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-semibold text-foreground uppercase tracking-wider">
                  All Tasks
                </h3>
                <div className="flex items-center gap-1.5">
                  {(
                    [
                      ["all", "All"],
                      ["queued", "Queued"],
                      ["in_progress", "Active"],
                      ["completed", "Done"],
                    ] as const
                  ).map(([value, label]) => (
                    <button
                      key={value}
                      onClick={() => setTaskFilter(value)}
                      className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${
                        taskFilter === value
                          ? "bg-foreground text-background"
                          : "bg-slate-100 text-muted-foreground hover:bg-slate-200"
                      }`}
                    >
                      {label}
                    </button>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                {filteredTasks.map((task) => (
                  <TaskCard key={task.id} task={task} />
                ))}
              </div>
              {filteredTasks.length === 0 && (
                <div className="rounded-xl border border-dashed border-slate-300 p-8 text-center">
                  <p className="text-sm text-muted-foreground">
                    No tasks match this filter.
                  </p>
                </div>
              )}
            </div>
          </div>

          {/* Right Sidebar */}
          <div className="space-y-6">
            {/* Agent Roster */}
            <Card className="border-slate-200 shadow-none">
              <CardHeader className="pb-3">
                <CardTitle className="text-base font-semibold flex items-center gap-2">
                  <Bot className="h-4 w-4 text-violet-500" />
                  Agent Roster
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                {MOCK_AGENTS.map((agent) => (
                  <AgentCard key={agent.id} agent={agent} compact />
                ))}
              </CardContent>
            </Card>

            {/* Recent Activity */}
            <Card className="border-slate-200 shadow-none">
              <CardHeader className="pb-3">
                <CardTitle className="text-base font-semibold flex items-center gap-2">
                  <Activity className="h-4 w-4 text-blue-500" />
                  Recent Activity
                </CardTitle>
              </CardHeader>
              <CardContent>
                <AgentActivityFeed
                  activities={MOCK_AGENT_ACTIVITY}
                  maxItems={8}
                />
              </CardContent>
            </Card>
          </div>
        </div>
      </div>

      {/* New Task Dialog */}
      <NewTaskDialog open={showNewTask} onOpenChange={setShowNewTask} />
    </PageTransition>
  );
};

export default AgentHub;

