import { useState, useEffect, useRef } from "react";
import { useParams, Link } from "react-router-dom";
import {
  ArrowLeft,
  Globe,
  Clock,
  AlertTriangle,
  Play,
  Pause,
  RotateCcw,
  Bot,
  Sparkles,
  ChevronRight,
  ExternalLink,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import { PageTransition } from "@/components/shared/PageTransition";
import { AgentAvatar } from "@/components/agents/AgentAvatar";
import { AgentStatusBadge } from "@/components/agents/AgentStatusBadge";
import { AgentMessageBubble } from "@/components/agents/AgentMessage";
import { cn } from "@/lib/utils";
import { formatRelativeDate } from "@/lib/score-utils";
import { agentEngine } from "@/lib/agent-engine";
import { MOCK_AGENTS, MOCK_AGENT_TASKS, MOCK_AGENT_MESSAGES } from "@/lib/mock-agents";
import type { AgentStatus } from "@/types/agents";

// ── Component ───────────────────────────────────────────────

const AgentWorkspace = () => {
  const { taskId } = useParams<{ taskId: string }>();
  const task = MOCK_AGENT_TASKS.find((t) => t.id === taskId);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const [, forceUpdate] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);

  // Subscribe to engine state changes
  useEffect(() => {
    const unsubscribe = agentEngine.subscribe(() => {
      forceUpdate((n) => n + 1);
    });
    return () => {
      unsubscribe();
      agentEngine.cleanup();
    };
  }, []);

  // Start watching the task
  useEffect(() => {
    if (!taskId) return;

    if (task?.status === "completed") {
      // Load all messages instantly for completed tasks
      agentEngine.loadCompletedTask(taskId);
    } else {
      // Progressive delivery for active tasks
      agentEngine.watchTask(taskId);
    }
  }, [taskId, task?.status]);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [agentEngine.getMessages(taskId ?? "").length]);

  if (!task) {
    return (
      <PageTransition>
        <div className="flex flex-col items-center justify-center py-20">
