                    </SidebarMenuButton>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter className="p-3">
        {/* Scan usage indicator */}
        {!collapsed && (
          <div className="mb-3 rounded-lg bg-white/5 p-3">
            <div className="flex items-center justify-between mb-1.5">
              <span className="text-[11px] text-sidebar-foreground/70">Scans this month</span>
              <span className="text-[11px] font-medium text-sidebar-primary-foreground">
                {user.scans_used}/{user.scan_limit}
              </span>
            </div>
            <Progress value={usagePercent} className="h-1.5" />
            <div className="mt-1.5 flex items-center gap-1.5">
              <Badge
                variant="outline"
                className="border-sidebar-border bg-transparent text-[10px] text-sidebar-foreground/70 capitalize px-1.5 py-0"
              >
                {user.plan} plan
              </Badge>
            </div>
          </div>
        )}

        <Separator className="mb-3 bg-sidebar-border" />

        {!collapsed ? (
          <Link
            to="/pricing"
            className="flex items-center justify-center gap-2 rounded-lg bg-gradient-to-r from-primary to-primary/80 px-4 py-2.5 text-sm font-medium text-primary-foreground transition-all hover:opacity-90 hover:shadow-lg hover:shadow-primary/20"
          >
            <Zap className="h-4 w-4" />
            Upgrade to Pro
          </Link>
        ) : (
          <Link
            to="/pricing"
            className="flex items-center justify-center rounded-lg bg-primary p-2 text-primary-foreground transition-opacity hover:opacity-90"
          >
            <Zap className="h-4 w-4" />
          </Link>
        )}
      </SidebarFooter>
    </Sidebar>
  );
}

